public long crtBruteForce(long[] a, long[] m) {
    long M = 1;
    for (long mi : m) M *= mi; // assumes M fits in long for the demo
    for (long x = 0; x < M; x++) {
        boolean ok = true;
        for (int i = 0; i < m.length; i++) {
            if (x % m[i] != a[i]) { ok = false; break; }
        }
        if (ok) return x;
    }
    return -1; // unreachable for valid coprime input
}

