import java.math.BigInteger;
import java.util.*;

public BigInteger crt(long[] a, long[] m) {
    // Iterative pairwise merge; BigInteger avoids overflow in the product.
    BigInteger x = BigInteger.ZERO;
    BigInteger mod = BigInteger.ONE;       // running modulus = product so far
    for (int i = 0; i < a.length; i++) {
        BigInteger ai = BigInteger.valueOf(a[i]);
        BigInteger mi = BigInteger.valueOf(m[i]);
        // solve x + mod*t == ai (mod mi):  t = (ai - x) * inv(mod, mi) mod mi
        BigInteger diff = ai.subtract(x).mod(mi);
        BigInteger inv = mod.modInverse(mi); // requires gcd(mod, mi) == 1
        BigInteger t = diff.multiply(inv).mod(mi);
        x = x.add(mod.multiply(t));
        mod = mod.multiply(mi);              // new modulus = product
        x = x.mod(mod);
    }
    return x.mod(mod); // canonical representative in [0, M)
}

